arguments.command:
python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')
for i, slide in enumerate(prs.slides):
    for shape in slide.shapes:
        if shape.has_text_frame:
            txt = shape.text_frame.text.strip()
            if txt:
                print(f'Slide {i+1} [{shape.shape_type}]: {txt[:100]}')
        elif shape.has_table:
            print(f'Slide {i+1} [TABLE]: rows={len(shape.table.rows)} cols={len(shape.table.columns)}')
        elif shape.has_chart:
            print(f'Slide {i+1} [CHART]: {shape.chart.chart_type}')
    print('---')
"
